# MUTANT players_off_by_one: generated by zoo/make_mutants.py from zoo/cfr.py. Do not edit.
"""Clean CFR+ and vanilla CFR over bluff-game-v1 files: the solver under test.

Floats on purpose: this is the kind of solver the checker grades, not part of the trusted base.
Every mutant in zoo/mutants/ is this file with one small, named edit (see zoo/make_mutants.py),
so `diff zoo/cfr.py zoo/mutants/<name>.py` shows the whole bug.

The solver carries the internal meters a real solver carries, and its stopping rule trusts them:

- self_exploitability: exploitability of the average strategy, computed by a best response
  that walks the solver's OWN model of the game (its own infoset keys, its own chance weights).
  This is Red/Black's eps_round: exact for the game the solver thinks it is solving.
- regret_meter: sum over both players of sum over infosets of max_a cumulative regret^+,
  divided by the iteration count (the classic average-regret bound; a heuristic under CFR+'s
  linear averaging, where it is still what people print).
- value_delta: change of the average profile's value to player 0 over the last `check_every`
  iterations (a per-probability delta never settles in rarely reached infosets, so real solvers
  watch the value).

The run reports "converged" when every meter is at or below its tolerance. One more meter is
reported but not part of the stopping rule, because it means something only on games with a
color-swap automorphism (Red/Black dealt from the 26/26 deck):

- color_swap_gap: the largest difference between the shipped row at an infoset and the shipped
  row at its color-swapped image (Red/Black Paper II's measured symmetry instrument), or None
  when no infoset's image is in the game.

    uv run zoo/cfr.py GAME.game.json OUT.strategy.json [--algo cfrplus|cfr] [--iters N]
"""

from __future__ import annotations

import argparse
import json
import sys
from fractions import Fraction

TOL_EXPLOIT = 1e-3
TOL_REGRET = 5e-2
TOL_DELTA = 1e-4
NUM_PLAYERS = 2
SWAP = str.maketrans("RB", "BR")


def num(s: str) -> float:
    return float(Fraction(s))


def _hand(h: str) -> str:
    """A dealt hand is written by color counts, reds first ("RB" is one of each)."""
    return "R" * h.count("R") + "B" * h.count("B")


def color_swap(s: str) -> str:
    """Exchange red and black in a Red/Black infoset or action label (Paper II, the color swap).

    Ordered tokens (reorders, bids, flips, discards) swap letter by letter. Unordered hands (the
    deal "p0|deal:RB" and the class "p0|start:R|RB", one hand per seat) swap and re-sort, so the
    image of a red-and-black hand is itself. With a 26/26 deck this is an automorphism of the game.
    Strings without R or B (every non-Red/Black game here) map to themselves.
    """
    out = []
    for tok in s.split(" "):
        head, sep, body = tok.partition(":")
        if sep and head.endswith(("|deal", "|start")):
            out.append(head + sep + "|".join(_hand(h.translate(SWAP)) for h in body.split("|")))
        else:
            out.append(tok.translate(SWAP))
    return " ".join(out)


class Solver:
    def __init__(self, game: dict, algo: str = "cfrplus") -> None:
        self.game = game
        self.algo = algo
        self.nodes = {n["id"]: n for n in game["nodes"]}
        self.root = game["root"]
        self.regret: dict[str, list[float]] = {}
        self.strat_sum: dict[str, list[float]] = {}
        self.actions: dict[str, list[str]] = {}  # solver key -> row labels
        self.owner: dict[str, int] = {}
        self.ix: dict[int, list[int]] = {}  # node id -> row position of each of the node's actions
        # solver key -> {infoset written to the strategy file: (row positions, the node's labels)}
        self.out_rows: dict[str, dict[str, tuple[list[int], list[str]]]] = {}
        self.t = 0
        self._register(self.root, ())

    # ----- the solver's model of the game -------------------------------------------------
    def key(self, node: dict, path: tuple) -> str:
        """The table key for a decision node. `path` is the chance labels on the way down."""
        return node["infoset"]

    def act_label(self, node: dict, label: str) -> str:
        """The row label of one of the node's actions. Nodes that share a key share a row, matched
        by label, so they may list their actions in any order."""
        return label

    def chance_outcomes(self, node: dict) -> list[tuple[float, int, str]]:
        return [(num(o["prob"]), o["child"], o["label"]) for o in node["outcomes"]]

    def _register(self, nid: int, path: tuple) -> None:
        node = self.nodes[nid]
        if node["kind"] == "chance":
            for _, child, label in self.chance_outcomes(node):
                self._register(child, path + (label,))
        elif node["kind"] == "decision":
            k = self.key(node, path)
            labels = [self.act_label(node, a["label"]) for a in node["actions"]]
            if k not in self.regret:
                n = len(node["actions"])
                self.regret[k] = [0.0] * n
                self.strat_sum[k] = [0.0] * n
                self.actions[k] = labels
                self.owner[k] = node["player"]
            if sorted(labels) != sorted(self.actions[k]) or self.owner[k] != node["player"]:
                raise ValueError(f"key {k!r} is shared by nodes with different players or actions")
            self.ix[nid] = [self.actions[k].index(lab) for lab in labels]
            self.out_rows.setdefault(k, {})[node["infoset"]] = (self.ix[nid], [a["label"] for a in node["actions"]])
            for a in node["actions"]:
                self._register(a["child"], path)

    # ----- regret matching ----------------------------------------------------------------
    def current(self, k: str) -> list[float]:
        pos = [max(r, 0.0) for r in self.regret[k]]
        s = sum(pos)
        n = len(pos)
        return [p / s for p in pos] if s > 0 else [1.0 / n] * n

    def average(self, k: str) -> list[float]:
        ss = self.strat_sum[k]
        s = sum(ss)
        n = len(ss)
        return [x / s for x in ss] if s > 0 else [1.0 / n] * n

    # ----- one traversal for the updating player p -----------------------------------------
    def traverse(self, nid: int, p: int, reach: list[float], path: tuple, pending: dict) -> float:
        """Returns the expected utility to p of the subtree; reach = [pi_0, pi_1, pi_chance]."""
        node = self.nodes[nid]
        kind = node["kind"]
        if kind == "terminal":
            u = num(node["payoff_p0"])
            return u if p == 0 else -u
        if kind == "chance":
            v = 0.0
            for prob, child, label in self.chance_outcomes(node):
                r = [reach[0], reach[1], reach[2] * prob]
                v += prob * self.traverse(child, p, r, path + (label,), pending)
            return v
        pl = node["player"]
        k = self.key(node, path)
        ix = self.ix[nid]
        row = self.current(k)
        sigma = [row[i] for i in ix]
        vals = []
        for a, act in enumerate(node["actions"]):
            r = list(reach)
            r[pl] = reach[pl] * sigma[a]
            vals.append(self.traverse(act["child"], p, r, path, pending))
        v = sum(s * x for s, x in zip(sigma, vals))
        if pl == p:
            cf = reach[1 - p] * reach[2]
            acc = pending.setdefault(k, [0.0] * len(vals))
            for a in range(len(vals)):
                acc[ix[a]] += cf * (vals[a] - v)
        else:
            w = self.avg_weight()
            ss = self.strat_sum[k]
            for a in range(len(sigma)):
                ss[ix[a]] += w * reach[pl] * sigma[a]
        return v

    def avg_weight(self) -> float:
        return float(self.t) if self.algo == "cfrplus" else 1.0

    def iterate(self) -> None:
        self.t += 1
        for p in range(1, NUM_PLAYERS):
            # Alternating updates: p's regrets move, and the opponent's average absorbs the
            # strategy it played this half-iteration. Updates are applied after the sweep so
            # an infoset's strategy is fixed for the whole traversal.
            pending: dict[str, list[float]] = {}
            self.traverse(self.root, p, [1.0, 1.0, 1.0], (), pending)
            for k, d in pending.items():
                reg = self.regret[k]
                for a in range(len(d)):
                    reg[a] += d[a]
                    if self.algo == "cfrplus":
                        reg[a] = max(reg[a], 0.0)

    # ----- output -------------------------------------------------------------------------
    def output_strategy(self, k: str) -> list[float]:
        return self.average(k)

    def strategy_probs(self) -> dict[str, dict[str, str]]:
        probs: dict[str, dict[str, str]] = {}
        for k in self.regret:
            row = self.output_strategy(k)
            for infoset, (ix, labels) in self.out_rows[k].items():
                probs[infoset] = {lab: repr(row[i]) for lab, i in zip(labels, ix)}
        return probs

    def color_swap_gap(self) -> float | None:
        """Largest |p(I, a) - p(swap I, swap a)| over the shipped rows, or None with no pairs."""
        probs = self.strategy_probs()
        gaps = [abs(float(row[a]) - float(probs[color_swap(i)][color_swap(a)]))
                for i, row in probs.items() if color_swap(i) != i and color_swap(i) in probs
                for a in row]
        return max(gaps) if gaps else None

    # ----- meters -------------------------------------------------------------------------
    def best_response_value(self, p: int) -> float:
        """Best value p can get against the opponent's AVERAGE strategy, in the solver's model."""
        cfr: dict[int, float] = {}
        node_key: dict[int, str] = {}
        members: dict[str, list[int]] = {}

        def down(nid: int, w: float, path: tuple) -> None:
            node = self.nodes[nid]
            cfr[nid] = w
            if node["kind"] == "chance":
                for prob, child, label in self.chance_outcomes(node):
                    down(child, w * prob, path + (label,))
            elif node["kind"] == "decision":
                k = self.key(node, path)
                node_key[nid] = k
                if node["player"] == p:
                    members.setdefault(k, []).append(nid)
                    for act in node["actions"]:
                        down(act["child"], w, path)
                else:
                    row = self.average(k)
                    for a, act in enumerate(node["actions"]):
                        down(act["child"], w * row[self.ix[nid][a]], path)

        down(self.root, 1.0, ())
        choice: dict[str, int] = {}
        memo: dict[int, float] = {}

        def value(nid: int) -> float:
            if nid in memo:
                return memo[nid]
            node = self.nodes[nid]
            if node["kind"] == "terminal":
                u = num(node["payoff_p0"])
                v = u if p == 0 else -u
            elif node["kind"] == "chance":
                v = sum(prob * value(child) for prob, child, _ in self.chance_outcomes(node))
            elif node["player"] == p:
                k = node_key[nid]
                if k not in choice:
                    n = len(node["actions"])
                    tot = [0.0] * n
                    for h in members[k]:
                        for a, act in enumerate(self.nodes[h]["actions"]):
                            tot[self.ix[h][a]] += cfr[h] * value(act["child"])
                    choice[k] = max(range(n), key=lambda a: tot[a])
                v = value(node["actions"][self.ix[nid].index(choice[k])]["child"])
            else:
                row = self.average(node_key[nid])
                sigma = [row[i] for i in self.ix[nid]]
                v = sum(s * value(act["child"]) for s, act in zip(sigma, node["actions"]))
            memo[nid] = v
            return v

        return value(self.root)

    def self_exploitability(self) -> float:
        return (self.best_response_value(0) + self.best_response_value(1)) / 2.0

    def regret_meter(self) -> float:
        tot = sum(max(max(r), 0.0) for r in self.regret.values())
        return tot / max(self.t, 1)

    def profile_value(self) -> float:
        """Value to player 0 of the average profile, in the solver's model."""

        def v(nid: int, path: tuple) -> float:
            node = self.nodes[nid]
            if node["kind"] == "terminal":
                return num(node["payoff_p0"])
            if node["kind"] == "chance":
                return sum(prob * v(c, path + (lab,)) for prob, c, lab in self.chance_outcomes(node))
            row = self.average(self.key(node, path))
            sigma = [row[i] for i in self.ix[nid]]
            return sum(s * v(act["child"], path) for s, act in zip(sigma, node["actions"]))

        return v(self.root, ())


def solve(game: dict, algo: str, iters: int, check_every: int) -> tuple[Solver, dict]:
    s = Solver(game, algo)
    prev = s.profile_value()
    meters = {}
    for i in range(1, iters + 1):
        s.iterate()
        if i % check_every == 0 or i == iters:
            val = s.profile_value()
            delta = abs(val - prev)
            prev = val
            meters = {
                "iterations": s.t,
                "self_exploitability": s.self_exploitability(),
                "regret_meter": s.regret_meter(),
                "value_delta": delta,
                "self_value_p0": val,
                "color_swap_gap": s.color_swap_gap(),
            }
            meters["converged"] = (
                meters["self_exploitability"] <= TOL_EXPLOIT
                and meters["regret_meter"] <= TOL_REGRET
                and meters["value_delta"] <= TOL_DELTA
            )
            if meters["converged"]:
                break
    return s, meters


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("game")
    ap.add_argument("out")
    ap.add_argument("--algo", choices=["cfrplus", "cfr"], default="cfrplus")
    ap.add_argument("--iters", type=int, default=2000)
    ap.add_argument("--check-every", type=int, default=100)
    ap.add_argument("--producer", default="zoo/cfr.py")
    ap.add_argument("--meters-out", help="write the final meters as JSON here")
    args = ap.parse_args(argv)
    sys.setrecursionlimit(100000)
    with open(args.game) as f:
        game = json.load(f)
    s, meters = solve(game, args.algo, args.iters, args.check_every)
    strategy = {"format": "bluff-strategy-v1", "game": game["name"], "producer": args.producer,
                "probs": s.strategy_probs()}
    with open(args.out, "w") as f:
        json.dump(strategy, f, indent=1)
        f.write("\n")
    if args.meters_out:
        with open(args.meters_out, "w") as f:
            json.dump(meters, f, indent=1)
            f.write("\n")
    print(json.dumps(meters))
    return 0


if __name__ == "__main__":
    sys.exit(main())
